// Token Radar: a pre-token protocol radar for make.fun's token-radar-01 (Node 22, standard library only).
//
// Reads the sealed snapshot (/input/snapshot.json, or --input <file|dir>), ranks every protocol whose
// DefiLlama record carries no token by a snapshot-calibrated implied launch value, and writes to
// /output (or MAKEFUN_OUTPUT_DIR, or --output <dir>):
//   board.json                the ranked board the gate reads, with the model's factors, risk, effort, cost and plan
//   dashboard/                this repository's static page, copied, plus two generated files:
//     0-evidence.md           a bounded summary of this run (coverage, held-out validation, worked valuations,
//                             classification, representative plans, source notes), sorted first so the dossier
//                             text shows it
//     zz-data.js              every row for the page as one script (no fetch, no network), packed by lib/pack.ts
//                             so a 4000-row board stays under the dashboard's 4 MiB limit; sorted last
//   screenshots/              this repository's screenshots (or --screenshots <dir>), copied
//   dossier.json              written last by the vendored make.fun library, unmodified
// lib/sources.json holds notes from official docs read on the date it records; it is static text, and
// nothing here makes a network request.
//
// Structure adapted from the make.fun starter's main.ts (MIT, (c) 2026 the make.fun team).
//   node main.ts --input <kit>/input/snapshot.json --output out

import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { evidenceSections, evidenceText } from './lib/evidence.ts';
import { pack, UNPACK } from './lib/pack.ts';
import { MODEL, parseSnapshot } from './lib/model.ts';
import { loadSources } from './lib/plans.ts';
import { BoardShortfall, boardIssue, boardRows, buildBoard, radarData } from './lib/radar.ts';
import { buildDossier } from './vendor/makefun-board.ts';

const here = fileURLToPath(new URL('.', import.meta.url));
const EVIDENCE = '0-evidence.md';
const DATA = 'zz-data.js';
const TEXT_MAX = 65_536;
const EVIDENCE_MAX = 16_384;
const IMAGE_NAME = /^[A-Za-z0-9_][A-Za-z0-9._-]{0,127}$/;

function arg(name: string, fallback: string): string {
  const at = process.argv.indexOf('--' + name);
  if (at >= 0 && at + 1 < process.argv.length) return process.argv[at + 1]!;
  const eq = process.argv.find((a) => a.startsWith('--' + name + '='));
  return eq === undefined ? fallback : eq.slice(name.length + 3);
}

function fail(msg: string, code = 1): never {
  process.stderr.write('token radar: ' + msg + '\n');
  process.exit(code);
}

const inputArg = arg('input', '/input');
const inputFile = inputArg.endsWith('.json') ? inputArg : join(inputArg, 'snapshot.json');
if (!existsSync(inputFile)) fail('no snapshot at ' + inputFile + ': pass --input <snapshot.json|directory>', 2);
const out = arg('output', process.env.MAKEFUN_OUTPUT_DIR ?? '/output');
const shotsDir = arg('screenshots', join(here, 'screenshots'));

let snapshot: ReturnType<typeof parseSnapshot>;
try {
  snapshot = parseSnapshot(readFileSync(inputFile, 'utf8'));
} catch (e) {
  fail('cannot read ' + inputFile + ': ' + (e instanceof Error ? e.message : String(e)), 2);
}
const book = loadSources();
let built: ReturnType<typeof buildBoard>;
try {
  built = buildBoard(snapshot, book);
} catch (e) {
  if (e instanceof BoardShortfall) fail('this snapshot cannot fill an honest board: ' + e.message, 3);
  throw e;
}
const rows = boardRows(built);
const issue = boardIssue(rows, snapshot);
if (issue !== null) fail('the board would fail the gate: ' + issue);

mkdirSync(out, { recursive: true });
writeFileSync(join(out, 'board.json'), JSON.stringify({
  as_of: snapshot.as_of,
  source: snapshot.source,
  model_version: MODEL.version,
  note: 'implied_value_usd is this entry\'s model estimate of what a token would be worth if the protocol\'s record stayed as it is; not a price, a forecast of a launch, or a promise of any reward.',
  rows,
}) + '\n');

function copyFiles(from: string, to: string): string[] {
  if (!existsSync(from)) return [];
  mkdirSync(to, { recursive: true });
  const copied: string[] = [];
  for (const name of readdirSync(from).sort()) {
    if (name.startsWith('.')) continue;
    const path = join(from, name);
    if (!statSync(path).isFile()) continue;
    copyFileSync(path, join(to, name));
    copied.push(name);
  }
  return copied;
}

const dash = copyFiles(join(here, 'dashboard'), join(out, 'dashboard')).filter((n) => n !== EVIDENCE && n !== DATA);
writeFileSync(join(out, 'dashboard', DATA), '// Token Radar data: all ' + built.rows.length + ' board rows and the calibration, generated by main.ts from the snapshot of ' + snapshot.as_of + '; summarised in ' + EVIDENCE + ' (packed: repeated text stored once; lib/pack.ts, unpacked below).\nwindow.RADAR=(' + UNPACK + ')(' + JSON.stringify(pack(radarData(snapshot, built, book) as never)) + ');\n');
const shots = copyFiles(shotsDir, join(out, 'screenshots')).filter((n) => /\.(png|jpe?g)$/i.test(n));
if (shots.length < 3) fail('screenshots/ holds ' + shots.length + ' images: hand in 3 (board, detail view, filtered view); see SCREENSHOTS.md');
for (const name of shots) if (!IMAGE_NAME.test(name)) fail('screenshots/' + name + ': use letters, digits and . _ -');

// The evidence file and the dossier. The dossier's text shows dashboard files whole in path order until
// 65,536 bytes, so the evidence (first) keeps only whole sections, at most EVIDENCE_MAX bytes, while the
// page's own source still fits whole after it; only zz-data.js (last) may be cut. The dossier is written last:
// the scorer rebuilds it from this /output and compares bytes.
const sections = evidenceSections(snapshot, built, book);
const caps = { text_max_bytes: TEXT_MAX, screenshots: { max: 4, max_bytes: 524_288 }, dashboard: { max_files: 400, max_bytes: 4_194_304 } };
let dossier: Uint8Array | null = null;
let kept = 0;
for (let n = sections.length; n >= 1 && dossier === null; n--) {
  const ev = evidenceText(sections.slice(0, n), EVIDENCE_MAX);
  writeFileSync(join(out, 'dashboard', EVIDENCE), ev.text);
  const doc = buildDossier(out, caps);
  const text = (JSON.parse(new TextDecoder().decode(doc)) as { text: string }).text;
  if ([EVIDENCE, ...dash].every((name) => text.includes(readFileSync(join(out, 'dashboard', name), 'utf8')))) { dossier = doc; kept = ev.kept; }
}
if (dossier === null) fail('the page source does not fit whole in the dossier text: shorten dashboard/ sources');
writeFileSync(join(out, 'dossier.json'), dossier);

const wl = rows.filter((r) => r.on_watchlist).length;
process.stdout.write(
  'token radar: ' + snapshot.protocols.length + ' protocols read, ' + rows.length + ' ranked (' + wl + '/' + snapshot.watchlist.length + ' watchlist), ' +
    built.setAside.length + ' set aside, ' + built.live.length + ' with a trading token\n' +
    'token radar: wrote board.json, dashboard/ (' + dash.length + ' source files + ' + EVIDENCE + ' with ' + kept + '/' + sections.length + ' sections + ' + DATA + '), screenshots/ (' + shots.length + ') and dossier.json to ' + out + '\n',
);
